pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        // Admissible domain: contract holds a nonzero balance; requested value exceeds it
        // but is a transferable amount (fits in a transfer-safe range).
        vm.deal(address(c), 1 wei);
        value = bound(value, 2, type(uint128).max); // value > 1 wei = balance
        bool ok;
        try c.withdraw(value) { ok = true; } catch { ok = false; }
        // Rule: over-withdrawing (value > balance) must always revert; the mutant
        // instead transfers the entire balance and succeeds.
        assertTrue(!ok);
    }
}

