pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v1, uint256 v2, uint256 extra) public {
        v1 = bound(v1, 0, 1 ether);
        v2 = bound(v2, 1, 1 ether);
        extra = bound(extra, 1, 1 ether);

        uint256 total = v1 + v2 + extra;

        // fund c through its payable fallback
        (bool sent, ) = address(c).call{value: total}("");
        assertTrue(sent);
        assertEq(address(c).balance, total);

        // owner is this test contract (deployer of c)
        c.withdraw(v1);
        // after the first withdrawal of v1, the remaining balance must be v2+extra,
        // so the second withdrawal of v2 is admissible and must leave exactly `extra`
        assertTrue(address(c).balance >= v2);
        c.withdraw(v2);

        // general rule: sequential withdrawals subtract exactly the requested values;
        // the mutant drains the whole balance on the first call, leaving 0 != extra
        assertTrue(address(c).balance == extra);
    }
}

