}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}
    fallback() external payable {}

    function test(uint v) public {
        require(v == 0);
        bool reverted = false;
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
}

